ml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:252:\"https://ja.wordpress.org/support/topic/%e3%83%96%e3%83%ad%e3%83%83%e3%82%af%e3%80%8c%e3%82%ae%e3%83%a3%e3%83%a9%e3%83%aa%e3%83%bc%e3%80%8d%e3%81%ab%e5%86%99%e7%9c%9f%e3%81%8c%e3%82%a2%e3%83%83%e3%83%97%e3%83%ad%e3%83%bc%e3%83%89%e3%81%a7/#post-11694636\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"返信先: ブロック「ギャラリー」に写真がアップロードできない\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:252:\"https://ja.wordpress.org/support/topic/%e3%83%96%e3%83%ad%e3%83%83%e3%82%af%e3%80%8c%e3%82%ae%e3%83%a3%e3%83%a9%e3%83%aa%e3%83%bc%e3%80%8d%e3%81%ab%e5%86%99%e7%9c%9f%e3%81%8c%e3%82%a2%e3%83%83%e3%83%97%e3%83%ad%e3%83%bc%e3%83%89%e3%81%a7/#post-11694636\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 01 Oct 2026 02:24:02 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:958:\"\n						\n						<p class=\"wp-block-paragraph\">ご連絡ありがとうございます。</p>\n\n\n\n<p class=\"wp-block-paragraph\">試してみる項目を拝見した結果、「他の端末からのアップロード」は試していなかったので、端末を準備してアップロードを行いました。<br />すると、問題なくアップロードできました。</p>\n\n\n\n<p class=\"wp-block-paragraph\">私が使用しているパソコンは、３２ビットパソコンなので、６４ビットパソコンとは動作結果が違うようです。<br />ブラウザのバージョンは同じでしたが、３２ビット版と６４ビット版で動作結果が違うということなのでしょう。<br />原因は私のパソコンにありました。</p>\n\n\n\n<p class=\"wp-block-paragraph\">お忙しい中、お手数をおかけし申し訳ありませんでした。<br />対応ありがとうございました。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"tarutoniflan\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:246:\"https://ja.wordpress.org/support/topic/%e6%9c%ac%e4%bd%93%e6%9b%b4%e6%96%b0%e6%99%82%e3%81%ab-disk-quota-exceeded-%e3%81%8c%e5%87%ba%e3%82%8b%ef%bc%88%e5%ae%b9%e9%87%8f%e3%81%ab%e3%81%af%e7%a9%ba%e3%81%8d%e3%81%82%e3%82%8a%ef%bc%89/#post-11694635\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:89:\"返信先: 本体更新時に Disk quota exceeded が出る（容量には空きあり）\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:246:\"https://ja.wordpress.org/support/topic/%e6%9c%ac%e4%bd%93%e6%9b%b4%e6%96%b0%e6%99%82%e3%81%ab-disk-quota-exceeded-%e3%81%8c%e5%87%ba%e3%82%8b%ef%bc%88%e5%ae%b9%e9%87%8f%e3%81%ab%e3%81%af%e7%a9%ba%e3%81%8d%e3%81%82%e3%82%8a%ef%bc%89/#post-11694635\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 01 Oct 2026 00:25:26 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:273:\"\n						\n						<p class=\"wp-block-paragraph\">ご連絡ありがとうございます。<br />解決いただいたようで何よりです！</p>\n\n\n\n<p class=\"wp-block-paragraph\">また何かありましたら、ご遠慮なくご質問くださいませ。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s: