7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"Nishimura\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:183:\"https://ja.wordpress.org/support/topic/wordpress%e6%99%82%e3%81%abftp%e3%83%a6%e3%83%bc%e3%82%b6%e3%83%bc%e3%82%92%e6%b1%82%e3%82%81%e3%82%89%e3%82%8c%e3%81%be%e3%81%99/#post-11694633\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:62:\"返信先: WordPress時にFTPユーザーを求められます\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:183:\"https://ja.wordpress.org/support/topic/wordpress%e6%99%82%e3%81%abftp%e3%83%a6%e3%83%bc%e3%82%b6%e3%83%bc%e3%82%92%e6%b1%82%e3%82%81%e3%82%89%e3%82%8c%e3%81%be%e3%81%99/#post-11694633\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 30 Sep 2026 12:17:41 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1309:\"\n						\n						<p class=\"wp-block-paragraph\"><a href=\"https://ja.wordpress.org/support/users/yukinobu/\" class=\"mention\" rel=\"nofollow ugc\">@yukinobu</a> <br /></p>\n\n\n\n<p class=\"wp-block-paragraph\">御親切にありがとうございます。<br />結論から申しますとSELinuxは問題ありません。</p>\n\n\n\n<p class=\"wp-block-paragraph\">9/28時点では私が作ったテスト用のサーバーで試していました。<br />SELINUXはEnforcingだったのでDisabledに変更することが必要でした。<br />その後、実際にお客様が使っているサーバーで確認したところ、<br />SELINUXはDisabledでした。(なぜそうなっているのかは不明です。)</p>\n\n\n\n<p class=\"wp-block-paragraph\">またディレクトリパーミッションは755で、ファイルは644だったので<br />パーミッション変更もしませんでした。<br />よって所有者変更のみが必要で、以下3コマンドのみ実行しました。<br />sudo chown -R apache /var/www<br />sudo chgrp -R apache /var/www<br />sudo systemctl restart httpd</p>\n\n\n\n<p class=\"wp-block-paragraph\">今の仕様が適切かどうかは難しいところですが、<br />「変更してください」とは言えないので突っ込んではおりません。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:11:\"wpcheck0916\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:252:\"https://ja.wordpress.org/support/topic/%e3%83%96%e3%83%ad%e3%83%83%e3%82%af%e3%80%8c%e3%82%ae%e3%83%a3%e3%83%a9%e3%83%aa%e3%83%bc%e3%80%8d%e3%81%ab%e5%86%99%e7%9c%9f%e3%81%8c%e3%82%a2%e3%83%83%e3%83%97%e3%83%ad%e3%83%bc%e3%83%89%e3%81%a7/#post-11694632\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"返信先: ブロック「ギャラリー」に写真がアップロードできない\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:252:\"https://ja.wordpress.org/support/topic/%e3%83%96%e3%83%ad%e3%83%83%e3%82%af%e3%80%8c%e3%82%ae%e3%83%a3%e3%83%a9%e3%83%aa%e3%83%bc%e3%80%8d%e3%81%ab%e5%86%99%e7%9c%9f%e3%81%8c%e3%82%a2%e3%83%83%e3%83%97%e3%83%ad%e3%83%bc%e3%83%89%e3%81%a7/#post-11694632\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 30 Sep 2026 03:41:25 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:948:\"\n						\n						<p class=\"wp-block-paragraph\">お知らせいただきありがとうございました。<br />内容を確認する限り、サーバー側やプラグインの問題ではなさそうですね。</p>\n\n\n\n<p class=\"wp-block-paragraph\">それでは、試しに以下操作をお試しいただけますでしょうか？</p>\n\n\n\n<p class=\"wp-block-paragraph\">① エラーが出ている画像以外のPNG画像をアップロードいただいて、エラーは起こりませんでしょうか？<br />② PNG以外の画像（JPEG画像など）でエラーは起こりますでしょうか？<br />③ 普段ご利用いただいているのとは異なるブラウザ・端末ではお試しいただいておりますでしょうか？<br />④ シークレットウィンドウ等の環境でアップロードいただいてもエラーは起こりますでしょうか？</p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:6:\"yinaba\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:252:\"https://ja.wordpress.org/support/topic/%e3%83%96%e3%83%ad%e3%83%83%e3%82%af%e3%80%8c%e3%82%ae%e3%83%a3%e3%83%a9%e3%83%aa%e3%83%bc%e3%80%8d%e3%81%ab%e5%86%99%e7%9c%9f%e3%81%8c%e3%82%a2%e3%83%83%e3%83%97%e3%83%ad%e3%83%bc%e3%83%89%e3%81%a7/#post-11694631\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"返信先: ブロック「ギャラリー」に写真がアップロードできない\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:252:\"https://ja.wordpress.org/support/topic/%e3%83%96%e3%83%ad%e3%83%83%e3%82%af%e3%80%8c%e3%82%ae%e3%83%a3%e3%83%a9%e3%83%aa%e3%83%bc%e3%80%8d%e3%81%ab%e5%86%99%e7%9c%9f%e3%81%8c%e3%82%a2%e3%83%83%e3%83%97%e3%83%ad%e3%83%bc%e3%83%89%e3%81%a7/#post-11694631\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 30 Sep 2026 02:41:21 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:822:\"\n						\n						<p class=\"wp-block-paragraph\">サイトヘルスを確認しました。次の通りです。</p>\n\n\n\n<p class=\"wp-block-paragraph\">使用中のプラグイン<br /><a href=\"https://imgur.com/cKLwUHQ\" rel=\"nofollow ugc\">https://imgur.com/cKLwUHQ</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">メディア処理<br /><a href=\"https://imgur.com/vMIsMmd\" rel=\"nofollow ugc\">https://imgur.com/vMIsMmd</a><br /><a href=\"https://imgur.com/5FJhZ7Y\" rel=\"nofollow ugc\">https://imgur.com/5FJhZ7Y</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">サーバー<br /><a href=\"https://imgur.com/eWsJ3il\" rel=\"nofollow ugc\">https://imgur.com/eWsJ3il</a><br /><a href=\"https://imgur.com/0YZP2Wr\" rel=\"nofollow ugc\">https://imgur.com/0YZP2Wr</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">以上よろしくお願いします。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"tarutoniflan\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:252:\"https://ja.wordpress.org/support/topic/%e3%83%96%e3%83%ad%e3%83%83%e3%82%af%e3%80%8c%e3%82%ae%e3%83%a3%e3%83%a9%e3%83%aa%e3%83%bc%e3%80%8d%e3%81%ab%e5%86%99%e7%9c%9f%e3%81%8c%e3%82%a2%e3%83%83%e3%83%97%e3%83%ad%e3%83%bc%e3%83%89%e3%81%a7/#post-11694630\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"返信先: ブロック「ギャラリー」に写真がアップロードできない\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:252:\"https://ja.wordpress.org/support/topic/%e3%83%96%e3%83%ad%e3%83%83%e3%82%af%e3%80%8c%e3%82%ae%e3%83%a3%e3%83%a9%e3%83%aa%e3%83%bc%e3%80%8d%e3%81%ab%e5%86%99%e7%9c%9f%e3%81%8c%e3%82%a2%e3%83%83%e3%83%97%e3%83%ad%e3%83%bc%e3%83%89%e3%81%a7/#post-11694630\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 29 Sep 2026 09:41:49 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1045:\"\n						\n						<p class=\"wp-block-paragraph\">早速ご回答ありがとうございます。</p>\n\n\n\n<p class=\"wp-block-paragraph\">次に、<strong>管理画面＞ツール＞サイトヘルス＞「情報」タブ</strong>の画面を開いていただき、以下項目のスクリーンショットをご共有いただけますでしょうか？</p>\n\n\n\n<ol>\n<li>使用中のプラグイン</li>\n\n\n\n<li>メディア処理</li>\n\n\n\n<li>サーバー</li>\n</ol>\n\n\n\n<p class=\"wp-block-paragraph\">なお、こちらのフォーラムでは直接画像を貼り付けることはできませんので、imgurなどの外部サービスをご利用いただけますと幸いです。</p>\n\n\n\n<p class=\"wp-block-paragraph\">サイトヘルスについては、詳しくは以下をご確認ください。<br /><a href=\"https://ja.wordpress.org/support/article/site-health-screen/\" rel=\"ugc\">https://ja.wordpress.org/support/article/site-health-screen/</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">どうぞよろしくお願いします。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:6:\"yinaba\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:252:\"https://ja.wordpress.org/support/topic/%e3%83%96%e3%83%ad%e3%83%83%e3%82%af%e3%80%8c%e3%82%ae%e3%83%a3%e3%83%a9%e3%83%aa%e3%83%bc%e3%80%8d%e3%81%ab%e5%86%99%e7%9c%9f%e3%81%8c%e3%82%a2%e3%83%83%e3%83%97%e3%83%ad%e3%83%bc%e3%83%89%e3%81%a7/#post-11694628\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"返信先: ブロック「ギャラリー」に写真がアップロードできない\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:252:\"https://ja.wordpress.org/support/topic/%e3%83%96%e3%83%ad%e3%83%83%e3%82%af%e3%80%8c%e3%82%ae%e3%83%a3%e3%83%a9%e3%83%aa%e3%83%bc%e3%80%8d%e3%81%ab%e5%86%99%e7%9c%9f%e3%81%8c%e3%82%a2%e3%83%83%e3%83%97%e3%83%ad%e3%83%bc%e3%83%89%e3%81%a7/#post-11694628\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 29 Sep 2026 07:57:14 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:960:\"\n						\n						<p class=\"wp-block-paragraph\">ありがとうございます。回答させていただきます。</p>\n\n\n\n<p class=\"wp-block-paragraph\">① 7.1.2にアップデートする前にご利用いただいていたWordPressのバージョンを教えていただけますでしょうか。<br />&gt;&gt;うろ覚えで申し訳ありませんが、Wordpress6.1だったと思います。PHP7.4でした。</p>\n\n\n\n<p class=\"wp-block-paragraph\">② ご利用いただいているサーバーはどちらになりますでしょうか。<br />&gt;&gt;VALUE SERVER です。</p>\n\n\n\n<p class=\"wp-block-paragraph\">③ 以下画像の赤枠からだと失敗して、青枠からだと成功するという理解でよろしいでしょうか？<br />&gt;&gt;そのとおりです。しばらく「アップロード中」のメッセージが出た後、「Webサーバーは&#8230;&#8230;」というメッセージが出る感じです。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"tarutoniflan\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:252:\"https://ja.wordpress.org/support/topic/%e3%83%96%e3%83%ad%e3%83%83%e3%82%af%e3%80%8c%e3%82%ae%e3%83%a3%e3%83%a9%e3%83%aa%e3%83%bc%e3%80%8d%e3%81%ab%e5%86%99%e7%9c%9f%e3%81%8c%e3%82%a2%e3%83%83%e3%83%97%e3%83%ad%e3%83%bc%e3%83%89%e3%81%a7/#post-11694627\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"返信先: ブロック「ギャラリー」に写真がアップロードできない\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:252:\"https://ja.wordpress.org/support/topic/%e3%83%96%e3%83%ad%e3%83%83%e3%82%af%e3%80%8c%e3%82%ae%e3%83%a3%e3%83%a9%e3%83%aa%e3%83%bc%e3%80%8d%e3%81%ab%e5%86%99%e7%9c%9f%e3%81%8c%e3%82%a2%e3%83%83%e3%83%97%e3%83%ad%e3%83%bc%e3%83%89%e3%81%a7/#post-11694627\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 29 Sep 2026 07:24:48 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1219:\"\n						\n						<p class=\"wp-block-paragraph\">こんにちは。</p>\n\n\n\n<p class=\"wp-block-paragraph\">原因の切り分けを行いたいため、以下のご質問にお答えいただくことは可能でしょうか？</p>\n\n\n\n<p class=\"wp-block-paragraph\">① 7.1.2にアップデートする前にご利用いただいていたWordPressのバージョンを教えていただけますでしょうか。<br />② ご利用いただいているサーバーはどちらになりますでしょうか。<br />③ 以下画像の赤枠からだと失敗して、青枠からだと成功するという理解でよろしいでしょうか？</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://imgur.com/a/NqJJJHR.png\" rel=\"nofollow ugc\">https://imgur.com/a/NqJJJHR.png</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\n\n\n\n<p class=\"wp-block-paragraph\">なお、ご参考までに、WordPress 6.8の時点で同様の不具合が起こる旨、不具合報告がなされておりますが、環境要因の可能性もあり、現時点で解決はしていないようです。<br /><a href=\"https://core.trac.wordpress.org/ticket/63294\" rel=\"nofollow ugc\">https://core.trac.wordpress.org/ticket/63294</a></p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:6:\"yinaba\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:252:\"https://ja.wordpress.org/support/topic/%e3%83%96%e3%83%ad%e3%83%83%e3%82%af%e3%80%8c%e3%82%ae%e3%83%a3%e3%83%a9%e3%83%aa%e3%83%bc%e3%80%8d%e3%81%ab%e5%86%99%e7%9c%9f%e3%81%8c%e3%82%a2%e3%83%83%e3%83%97%e3%83%ad%e3%83%bc%e3%83%89%e3%81%a7/#post-11694626\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:75:\"ブロック「ギャラリー」に写真がアップロードできない\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:252:\"https://ja.wordpress.org/support/topic/%e3%83%96%e3%83%ad%e3%83%83%e3%82%af%e3%80%8c%e3%82%ae%e3%83%a3%e3%83%a9%e3%83%aa%e3%83%bc%e3%80%8d%e3%81%ab%e5%86%99%e7%9c%9f%e3%81%8c%e3%82%a2%e3%83%83%e3%83%97%e3%83%ad%e3%83%bc%e3%83%89%e3%81%a7/#post-11694626\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 29 Sep 2026 06:00:26 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:961:\"\n						\n						<p class=\"wp-block-paragraph\">初めて投稿します。</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress7.1.2に更新した後、ブロック「ギャラリー」に写真（png形式）をアップロードすると、「Web サーバーはこの画像に対してレスポンシブな画像サイズを生成できません。アップロードする前に JPEG または PNG に変換してください。」というメッセージが表示され、アップロードできません。</p>\n\n\n\n<p class=\"wp-block-paragraph\">メディアライブラリに同じ写真（png形式）を追加すると、問題なくアップロードでき、ブロック「ギャラリー」に追加することができるのですが、何か対処方法はないでしょうか。</p>\n\n\n\n<p class=\"wp-block-paragraph\">使用している状態<br />テーマ：Twenty Twenty<br />PHPバージョン：PHP 8.3<br />写真のサイズ：718KB</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"tarutoniflan\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:3:{s:4:\"href\";s:44:\"https://ja.wordpress.org/support/forums/feed\";s:3:\"rel\";s:4:\"self\";s:4:\"type\";s:19:\"application/rss+xml\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}}}}s:4:\"type\";i:128;s:7:\"headers\";a:10:{s:6:\"server\";s:5:\"nginx\";s:4:\"date\";s:29:\"Thu, 01 Oct 2026 04:38:17 GMT\";s:12:\"content-type\";s:34:\"application/rss+xml; charset=UTF-8\";s:4:\"vary\";s:37:\"Accept-Encoding, accept, content-type\";s:6:\"x-olaf\";s:3:\"⛄\";s:12:\"x-robots-tag\";s:15:\"noindex, follow\";s:15:\"x-frame-options\";s:10:\"SAMEORIGIN\";s:16:\"content-encoding\";s:4:\"gzip\";s:7:\"alt-svc\";s:5:\"clear\";s:4:\"x-nc\";s:9:\"HIT dca 2\";}s:5:\"build\";i:1760643936;s:21:\"cache_expiration_time\";i:1790872697;s:23:\"__cache_expiration_time\";i:1790872697;}','off');
